from __future__ import annotations
import argparse
from .common import record, run_purpose

PURPOSE = 'code-repair'
CATALOG = [{'id': 'repair-singleflight-cache-fill', 'concept': 'singleflight-cache-fill', 'domain': 'software-engineering', 'subdomain': 'caching', 'difficulty': 'advanced', 'question': 'A cache miss causes every concurrent request for the same key to start the same expensive backend load. Repair the design so one load is shared without serializing unrelated keys.', 'answer': 'Maintain an in-flight entry keyed by the cache key. The first miss creates the load; later misses for the same key await that same result instead of starting another backend request. Remove the in-flight entry when the load completes, including failure paths, so later requests can retry. Do not use one global mutex around all cache fills because unrelated keys should proceed independently. Define whether failures are briefly cached or immediately retryable, and preserve request cancellation semantics without cancelling shared work merely because one waiter disconnects.', 'verification_details': 'Must coalesce concurrent fills per key, avoid global serialization, clean up in-flight state on success/failure, and define cancellation/failure behavior.', 'tags': ['cache', 'singleflight', 'concurrency', 'stampede'], 'verification_method': 'rubric'}, {'id': 'repair-transaction-retry-scope', 'concept': 'transaction-retry-whole-unit', 'domain': 'software-engineering', 'subdomain': 'database-concurrency', 'difficulty': 'expert', 'question': 'Code retries only the final SQL statement after a serialization failure, while earlier reads and writes from the transaction are reused. Repair the retry boundary.', 'answer': 'Retry the entire logical transaction from a fresh transaction context. A serialization/deadlock-style abort invalidates assumptions made by earlier reads and writes, so replaying only the last statement can commit a result based on stale observations. Roll back the failed transaction, apply bounded retry with jitter/backoff where appropriate, then re-run all transaction logic. External side effects must not be repeated blindly; move them behind an outbox/idempotent boundary or otherwise make them safe across retries.', 'verification_details': 'Must retry the complete transaction from fresh reads, roll back the failed attempt, bound retries, and prevent duplicated external side effects.', 'tags': ['database', 'transaction', 'serialization', 'retry'], 'verification_method': 'rubric'}, {'id': 'repair-recvmsg-control-truncation', 'concept': 'recvmsg-control-truncation-check', 'domain': 'systems-programming', 'subdomain': 'unix-sockets', 'difficulty': 'expert', 'question': 'A Unix-domain socket receives file descriptors with `recvmsg()`, but the code parses ancillary data without checking whether the control buffer was truncated. Repair the receive path.', 'answer': 'Provide a control buffer large enough for the expected ancillary data and inspect `msg_flags` after `recvmsg()`. If `MSG_CTRUNC` is set, reject the message and do not trust or partially consume the descriptor set because ancillary data was truncated. Iterate control messages only with the standard `CMSG_*` helpers and validate level/type/length before using payloads. Close any descriptors already obtained on later validation failure to avoid leaks.', 'verification_details': 'Must check MSG_CTRUNC, validate ancillary headers with CMSG helpers, reject truncated control data, and close received descriptors on subsequent failure.', 'tags': ['recvmsg', 'scm-rights', 'ancillary-data', 'fd-passing'], 'verification_method': 'rubric'}, {'id': 'repair-ssize-size-conversion', 'concept': 'ssize-to-size-checked-conversion', 'domain': 'systems-programming', 'subdomain': 'integer-safety', 'difficulty': 'intermediate', 'question': 'A function stores the return value of `read()` directly into `size_t` and then tests whether it is greater than zero. Repair the error handling.', 'answer': 'Store the return value in `ssize_t`. Test negative values for errors before converting to an unsigned size type; handle zero as EOF; only convert a positive result to `size_t` after those checks. Assigning `-1` directly to `size_t` produces a very large unsigned value, so a later `> 0` check can treat an error as a huge successful read.', 'verification_details': 'Must keep read() result in ssize_t until negative/zero cases are handled and only then convert positive counts to size_t.', 'tags': ['posix', 'read', 'integer-conversion', 'error-handling'], 'verification_method': 'rubric'}, {'id': 'repair-robust-mutex-owner-dead', 'concept': 'robust-mutex-owner-dead-recovery', 'domain': 'operating-systems', 'subdomain': 'synchronization', 'difficulty': 'expert', 'question': 'A process-shared robust mutex is used to protect shared memory. After the owner crashes, the next locker treats `EOWNERDEAD` as an ordinary failure and exits. Repair the recovery protocol.', 'answer': 'When locking returns `EOWNERDEAD`, the caller owns the mutex but the protected state may be inconsistent. Validate or repair the shared state while holding the mutex, then call the robust-mutex consistency operation before unlocking. If the state cannot be repaired, do not mark it consistent; the mutex should become unusable according to the API so corruption is not silently accepted. Ordinary success and non-recoverable errors remain separate paths.', 'verification_details': 'Must recognize that EOWNERDEAD grants ownership with suspect state, repair/validate under the lock, mark consistent only after successful recovery, and preserve unrecoverable handling.', 'tags': ['pthread', 'robust-mutex', 'shared-memory', 'recovery'], 'verification_method': 'rubric'}, {'id': 'repair-refcount-release-order', 'concept': 'atomic-refcount-final-release', 'domain': 'computer-architecture', 'subdomain': 'memory-ordering', 'difficulty': 'advanced', 'question': 'An intrusive atomic reference count decrements with relaxed ordering and immediately destroys the object when the count reaches zero. Repair the final-release ordering so prior writes by releasing threads are visible before destruction.', 'answer': 'Use an atomic decrement with release semantics for ordinary releases and, on the transition to zero, establish acquire ordering before destruction (for example an acquire fence paired with the release sequence, or an acquire-release decrement depending on the implementation pattern). The final thread must not destroy the object before synchronization makes prior writes visible. The exact primitive should follow the language memory model and established refcount pattern; relaxed-only final release is insufficient when destruction depends on prior writes.', 'verification_details': 'Must establish release ordering on decrements and acquire synchronization on the zero transition before destruction, with reasoning tied to the language memory model.', 'tags': ['atomics', 'refcount', 'memory-ordering', 'lifetime'], 'verification_method': 'rubric'}, {'id': 'repair-systemd-execstart-redirection', 'concept': 'systemd-execstart-no-shell-redirection', 'domain': 'linux-infrastructure', 'subdomain': 'systemd', 'difficulty': 'intermediate', 'question': 'A systemd unit contains `ExecStart=/usr/bin/tool --dump > /var/lib/app/out.txt`, but the program receives `>` as an argument instead of redirecting output. Repair the unit without invoking an unnecessary shell.', 'answer': "systemd does not interpret shell redirection syntax in `ExecStart=`. Keep `ExecStart=/usr/bin/tool --dump` and configure output with the unit's standard-output directives, for example `StandardOutput=file:/var/lib/app/out.txt` or the appropriate append/file target supported by the deployment. Use a shell only when shell semantics are genuinely required, because adding `/bin/sh -c` introduces quoting, environment, and security complexity.", 'verification_details': 'Must explain that ExecStart is not shell-parsed, move redirection to systemd output configuration, and avoid adding a shell without need.', 'tags': ['systemd', 'execstart', 'stdout', 'configuration'], 'verification_method': 'rubric'}, {'id': 'repair-isr-ring-index', 'concept': 'isr-main-ring-buffer-index-synchronization', 'domain': 'embedded-systems', 'subdomain': 'interrupt-concurrency', 'difficulty': 'advanced', 'question': 'An ISR writes bytes into a ring buffer and advances `head`; the main loop consumes bytes and advances `tail`. The indices are multi-byte values on an 8-bit MCU and are accessed without synchronization. Repair the design.', 'answer': 'Ensure each shared index is accessed atomically for the target. On an 8-bit MCU, a wider index may tear, so either choose an index width with atomic naturally aligned access, use target-supported atomics, or briefly mask the relevant interrupt while the main context snapshots/updates the shared index. Preserve the single-producer/single-consumer ownership rule: ISR owns `head`, main owns `tail`, and use the compiler/language synchronization required for visibility. Keep interrupt-disabled sections short.', 'verification_details': 'Must address torn multi-byte index access, preserve SPSC ownership, use target-appropriate atomicity/critical sections, and keep interrupt masking bounded.', 'tags': ['embedded', 'ring-buffer', 'isr', 'atomicity'], 'verification_method': 'rubric'}, {'id': 'repair-udp-truncation', 'concept': 'udp-message-truncation-detection', 'domain': 'networking', 'subdomain': 'udp', 'difficulty': 'advanced', 'question': 'A UDP receiver uses a fixed buffer and treats every successful `recvmsg()` as a complete datagram. Repair it so oversized datagrams are detected rather than silently parsed as complete messages.', 'answer': 'Use an API mode that exposes truncation, such as inspecting `MSG_TRUNC` in `msg_flags` after `recvmsg()` (with platform semantics understood). If truncation occurred, reject the datagram or use a strategy that first determines the required size; do not parse the prefix as though it were a complete message. Keep protocol-level maximum lengths and reject datagrams larger than that limit even if memory is available.', 'verification_details': 'Must detect datagram truncation through recvmsg/MSG_TRUNC or equivalent, reject incomplete messages, and enforce a protocol maximum.', 'tags': ['udp', 'recvmsg', 'truncation', 'framing'], 'verification_method': 'rubric'}, {'id': 'repair-secret-compare', 'concept': 'constant-time-secret-comparison', 'domain': 'secure-engineering', 'subdomain': 'side-channels', 'difficulty': 'advanced', 'question': 'Authentication code compares two fixed-length secret MAC values with a normal byte-string equality function that can stop at the first mismatch. Repair the comparison.', 'answer': 'Use a vetted constant-time comparison primitive intended for secrets, after separately validating that the inputs have the required fixed length. Do not hand-roll an early-exit loop. The surrounding code must also avoid leaking secret-dependent information through logging or distinct error paths. Constant-time comparison addresses timing leakage in the equality check; it does not compensate for using an insecure MAC or exposing secrets elsewhere.', 'verification_details': 'Must use a vetted constant-time comparison for fixed-length secrets, validate lengths separately, and avoid claiming this fixes unrelated cryptographic weaknesses.', 'tags': ['constant-time', 'mac', 'timing', 'authentication'], 'verification_method': 'rubric'}]

FAMILIES = [
    {
        "id": x["id"],
        "concept": x["concept"],
        "domain": x["domain"],
    }
    for x in CATALOG
]
BY_ID = {x["id"]: x for x in CATALOG}

def build(family, rng, rid, _difficulty):
    x = BY_ID[family["id"]]
    return record(
        rid,
        x["domain"],
        x["subdomain"],
        PURPOSE,
        x["difficulty"],
        x["question"],
        x["answer"],
        x["verification_method"],
        x["verification_details"],
        x["tags"],
    )

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--records", type=int, default=len(FAMILIES))
    ap.add_argument("--seed", type=int, default=20260914)
    args = ap.parse_args()
    run_purpose(
        purpose=PURPOSE,
        families=FAMILIES,
        build=build,
        records_requested=args.records,
        seed=args.seed,
    )

if __name__ == "__main__":
    main()
